import { TableHeadCell } from "../primitives/table/table-head-cell";
import { TableRow } from "../primitives/table/table-row";
import { Text } from "../primitives/text/text";
import type { Job, Department, JobLabels } from "../blocks/job-board.types";

export type JobCardsProps = {
  jobs: Job[];
  departments: Department[];
  labels: JobLabels;
  layout?: "grid" | "grouped" | "table";
  salary?: "show" | "hide";
};

export function JobCards({ jobs, departments, labels, layout = "grid", salary = "hide" }: JobCardsProps) {
  return (
    <>
      {((layout as string) === "table") ? (
        <Box class="w-full overflow-x-auto rounded inset-ring inset-ring-border">
          <Table class="w-full text-left text-sm" data-testid="job-table">
            <TableCaption class="sr-only">
              {labels.caption}
            </TableCaption>
            <TableHead class="bg-muted">
              <TableRow>
                <TableHeadCell scope="col" class="px-4 py-2">
                  {labels.role}
                </TableHeadCell>
                <TableHeadCell scope="col" class="hidden py-2 md:table-cell">
                  {labels.team}
                </TableHeadCell>
                <TableHeadCell scope="col" class="hidden py-2 sm:table-cell">
                  {labels.location}
                </TableHeadCell>
                <TableHeadCell scope="col" class="py-2">
                  {labels.type}
                </TableHeadCell>
                {((salary as string) === "show") ? (
                  <TableHeadCell scope="col" class="hidden py-2 md:table-cell">
                    {labels.salary}
                  </TableHeadCell>
                ) : null}
                <TableHeadCell scope="col" class="py-2 pr-4">
                  <Inline class="sr-only">
                    {labels.apply}
                  </Inline>
                </TableHeadCell>
              </TableRow>
            </TableHead>
