              <For each={jobs ?? []}>{(j) => (
                <TableRow class="border-t border-border" data-testid="item">
                  <TableCell class="px-4 py-4 font-medium">
                    {j.title}
                  </TableCell>
                  <TableCell class="hidden md:table-cell">
                    {departments.filter((i) => !j.dept || i["id"] === j.dept)[0]?.name ?? ""}
                  </TableCell>
                  <TableCell class="hidden sm:table-cell">
                    {j.location}
                  </TableCell>
                  <TableCell>
                    {j.type}
                  </TableCell>
                  {((salary as string) === "show") ? (
                    <TableCell class="hidden md:table-cell">
                      {j.salary}
                    </TableCell>
                  ) : null}
                  <TableCell class="pr-4 text-right">
                    <Link href="#/careers" variant="default" class="font-medium">
                      {labels.apply}
                    </Link>
                  </TableCell>
                </TableRow>
              )}</For>
            </TableBody>
          </Table>
        </Box>
      ) : (
        <Grid cols="1-2" class="gap-4" data-testid="items">
          <For each={jobs ?? []}>{(j) => (
            <Stack gap="4" class="rounded bg-card inset-ring inset-ring-border p-6" data-testid="item">
              <Stack gap="2">
                <Text size="lg" weight="semibold">
                  {j.title}
                </Text>
                <Group gap="4" class="flex-wrap text-sm text-muted-foreground">
                  <Group gap="2" align="center">
                    <LucideIcon name="briefcase" size={16} />
                    <Inline>
                      {j.type}
                    </Inline>
                  </Group>
                  <Group gap="2" align="center">
                    <LucideIcon name="map-pin" size={16} />
                    <Inline>
                      {j.location}
                    </Inline>
                  </Group>
                  <Group gap="2" align="center">
                    <LucideIcon name="calendar" size={16} />
                    <Inline>
                      {j.posted}
                    </Inline>
                  </Group>
                </Group>
              </Stack>
              {((salary as string) === "show") ? (
                <Text size="base" weight="semibold" data-testid="salary">
                  {j.salary}
                </Text>
              ) : null}
              <Group gap="4" align="center" justify="between" class="mt-auto">
                <Badge variant="secondary" size="default">
                  {departments.filter((i) => !j.dept || i["id"] === j.dept)[0]?.name ?? ""}
                </Badge>
                <Link href="#/careers" variant="default" class="inline-flex items-center gap-2 text-sm font-medium">
                  {labels.apply}
                  <LucideIcon name="arrow-right" size={16} />
                </Link>
              </Group>
            </Stack>
          )}</For>
        </Grid>
      )}
    </>
  );
}
